begin;

-- Chongwe ADM2 boundary from geoBoundaries gbOpen, Zambia ADM2 simplified
-- release commit 9469f09, shapeID 96606910B32717004733154 (source: GRID3).
-- Coordinates are GeoJSON [longitude, latitude]. Keep this provenance with
-- any future boundary replacement and re-run the inclusion regression suite.
alter table private.pilot_service_settings
  add column if not exists service_area_label text,
  add column if not exists service_area_polygon jsonb;

alter table private.pilot_service_settings
  drop constraint if exists pilot_service_area_polygon_valid,
  add constraint pilot_service_area_polygon_valid check (
    service_area_polygon is null or (
      jsonb_typeof(service_area_polygon) = 'array'
      and jsonb_array_length(service_area_polygon) >= 4
    )
  );

create or replace function private.point_in_polygon(
  p_lat double precision,
  p_lng double precision,
  p_polygon jsonb
)
returns boolean language sql immutable security definer set search_path = '' as $$
  with points as (
    select ordinality::integer as position,
      (coordinate ->> 0)::double precision as longitude,
      (coordinate ->> 1)::double precision as latitude
    from jsonb_array_elements(p_polygon) with ordinality as item(coordinate, ordinality)
  ), edges as (
    select current.longitude as x1, current.latitude as y1,
      coalesce(next.longitude, first_value(current.longitude) over (order by current.position)) as x2,
      coalesce(next.latitude, first_value(current.latitude) over (order by current.position)) as y2
    from points current
    left join points next on next.position = current.position + 1
  )
  select coalesce(
    bool_or(
      abs((p_lng - x1) * (y2 - y1) - (p_lat - y1) * (x2 - x1)) < 1e-10
      and p_lng between least(x1, x2) - 1e-10 and greatest(x1, x2) + 1e-10
      and p_lat between least(y1, y2) - 1e-10 and greatest(y1, y2) + 1e-10
    )
    or mod(count(*) filter (
      where (y1 > p_lat) <> (y2 > p_lat)
        and p_lng < (x2 - x1) * (p_lat - y1) / nullif(y2 - y1, 0) + x1
    ), 2) = 1,
    false
  ) from edges
$$;
revoke all on function private.point_in_polygon(double precision,double precision,jsonb) from public, anon, authenticated;

