create or replace function private.pilot_point_allowed(p_lat double precision, p_lng double precision)
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select
    p_lat between -90 and 90 and p_lng between -180 and 180 and
    case
      when service_area_polygon is not null then private.point_in_polygon(p_lat, p_lng, service_area_polygon)
      else 6371.0088 * 2 * asin(sqrt(least(1.0, greatest(0.0,
        power(sin(radians(p_lat - center_latitude) / 2), 2)
        + cos(radians(center_latitude)) * cos(radians(p_lat))
        * power(sin(radians(p_lng - center_longitude) / 2), 2))))) <= radius_km
    end
  from private.pilot_service_settings where singleton), false)
$$;
revoke all on function private.pilot_point_allowed(double precision,double precision) from public, anon;
grant execute on function private.pilot_point_allowed(double precision,double precision) to authenticated, service_role;

commit;
